#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT 1024
#define OUT_BUF_SIZE 2048

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    if (strlen(input) > MAX_INPUT) {
        puts("INVALID");
        return 0;
    }
    char out[OUT_BUF_SIZE];
    size_t out_len = 0;
    if (strcmp(mode, "escape") == 0) {
        for (size_t i = 0; input[i] != '\0'; ++i) {
            unsigned char c = (unsigned char)input[i];
            switch (c) {
                case '\\':
                    out[out_len++] = '\\';
                    out[out_len++] = '\\';
                    break;
                case '"':
                    out[out_len++] = '\\';
                    out[out_len++] = '"';
                    break;
                case '\n':
                    out[out_len++] = '\\';
                    out[out_len++] = 'n';
                    break;
                case '\t':
                    out[out_len++] = '\\';
                    out[out_len++] = 't';
                    break;
                default:
                    out[out_len++] = c;
                    break;
            }
        }
        out[out_len] = '\0';
        puts(out);
    } else if (strcmp(mode, "unescape") == 0) {
        for (size_t i = 0; input[i] != '\0'; ++i) {
            if (input[i] == '\\') {
                char next = input[i + 1];
                if (next == '\0') {
                    puts("INVALID");
                    return 0;
                }
                switch (next) {
                    case '\\': out[out_len++] = '\\'; break;
                    case '"': out[out_len++] = '"'; break;
                    case 'n': out[out_len++] = '\n'; break;
                    case 't': out[out_len++] = '\t'; break;
                    default:  out[out_len++] = next; break; // treat unknown escape as literal
                }
                ++i; // skip the escaped character
            } else {
                out[out_len++] = input[i];
            }
        }
        out[out_len] = '\0';
        puts(out);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
